/* [Inlined Multi-Tab] shaderSource.js */
import Olon, { Data } from "https://cdn.jsdelivr.net/npm/olon@0.0.0/src/Olon.js"
/* [Inlined Multi-Tab] tools.js */

const MAX_AMOUNT = 100000
const MIN_AGE = 1.01
const MAX_AGE = 2.15
const BIRTH_RATE = 0.5

const ol = Olon(990, 690)
ol.enableCanvas2D()

let mousePos = [0, 0];
let mouseInside = true;
let spawnAtMouse = false;
let spawnFrames = 0;

// --- 1. 定义全局手势变量 ---
let handpose;
let video;
let hands = [];
let handActive = false;
let handPos = [0, 0];
let spawnAtHand = false;

// 使用 window 的 mousemove 事件，避免画布层级或加载时序问题
window.addEventListener('mousemove', (e) => {
    if (ol.mouseX >= -1 && ol.mouseX <= 1 &&
        ol.mouseY >= -1 && ol.mouseY <= 1) {
        mouseInside = true;
        mousePos[0] = ol.mouseX * 0.75;
        mousePos[1] = ol.mouseY * 0.75;
    } else {
        mouseInside = false;
    }
});

// 鼠标离开窗口时彻底关闭引力
window.addEventListener('click', () => {
    mouseInside = true;
	spawnAtMouse = true;
    spawnFrames = 24;   // 持续 2 帧，让一些粒子重生在鼠标处
	// console.log(spawnAtMouse);
});

ol.blend({
	sfactor: ol.SRC_ALPHA,
	dfactor: ol.ONE_MINUS_SRC_ALPHA,
})
ol.enableBlend()

const TFV = ["vPosition", "vAge", "vLife", "vVel", "vForce", "vType"]
const updateProgram = ol.createProgram(UPDATE_VERT, UPDATE_FRAG, TFV)
const renderProgram = ol.createProgram(RENDER_VERT, RENDER_FRAG)

const aPosition = { name: "aPosition", unit: "f32", size: 2 }
const aAge = { name: "aAge", unit: "f32", size: 1 }
const aLife = { name: "aLife", unit: "f32", size: 1 }
const aVel = { name: "aVel", unit: "f32", size: 2 }
const aForce = { name: "aForce", unit: "f32", size: 2 } // 新增：2个 float (XY)
const aType = { name: "aType", unit: "f32", size: 1 }
const attributes = [aPosition, aAge, aLife, aVel, aForce, aType]

const particleData = []
for (let i = 0; i < MAX_AMOUNT; i++) {
	const life = random(MIN_AGE, MAX_AGE)
	particleData.push(0, 0) // aPosition
	particleData.push(life + 1) // aAge
	particleData.push(life) // aLife
	particleData.push(0, 0) // aVel
	particleData.push(0, 0) // aForce (初始化为0)
	particleData.push(0) // aType
}
const initData = Data(particleData)

const buffer0 = ol.createBuffer(initData, ol.STREAM_DRAW)
const buffer1 = ol.createBuffer(initData, ol.STREAM_DRAW)

const vao0 = ol.createVAO(updateProgram, { 
	buffer: buffer0,
	stride: 4 * 9, // 直接与particl的属性的字节数相关
	attributes,
})
const vao1 = ol.createVAO(updateProgram, {
	buffer: buffer1,
	stride: 4 * 9,
	attributes,
})

const buffers = [buffer0, buffer1]
const vaos = [vao0, vao1]
let [read, write] = [0, 1]
let [lastTime, bornAmount] = [0, 0]

ol.uniform("uRandom", [random() * 1024, random() * 1024])

ol.render(() => {
	const time = ol.frame / 60
	const timeDelta = time - lastTime
	lastTime = time

	const nextAmount = floor(bornAmount + BIRTH_RATE * 1000)
	bornAmount = min(MAX_AMOUNT, nextAmount)

	ol.clearColor(0, 0, 0, 0.25)
	ol.clearDepth()

	// console.log();

	if (spawnFrames > 0) {
        spawnFrames--;
        if (spawnFrames === 0) spawnAtMouse = false;
    }

	// console.log(spawnAtMouse);

	ol.use({ program: updateProgram }).run(() => {
		ol.transformFeedback(vaos[read], buffers[write], ol.POINTS, () => {
			ol.uniform("uTimeDelta", timeDelta)
			ol.uniform("uTime", time)
			ol.uniform('uSpawnAtMouse', spawnAtMouse);
			ol.uniform('uMouse', mouseInside ? mousePos : [0, 0]);
    ol.uniform('uMouseActive', mouseInside ? 1.0 : 0.0);
			ol.points(0, bornAmount)
		})
	})

	ol.use({
		program: renderProgram,
		VAO: vaos[write],
	}).run(() => ol.points(0, bornAmount))

	// swap
	;[read, write] = [write, read]
})




// === Tab: shaderSource.js ===

import * as Shox from "https://cdn.jsdelivr.net/npm/shox@1.1.0/src/Shox.js"

const UPDATE_VERT = `
	precision mediump float;

	uniform float uTimeDelta;
	uniform float uTime;
	uniform vec2 uRandom;
	uniform vec2 uMouse;
	uniform float uMouseActive;
	uniform bool uSpawnAtMouse; // 允许保留 bool uniform

	in vec2 aPosition;
	in float aAge;
	in float aLife;
	in vec2 aVel;
	in vec2 aForce;
	in float aType;


	// 顺序必须严格对应 JS 中的 TFV 数组
	out vec2 vPosition;
	out float vAge;
	out float vLife;
	out vec2 vVel;
	out vec2 vForce;
	out float vType; // 使用 float 传递标记

	${Shox.noiseMath}
	${Shox.snoise3D}
	${Shox.hash}

void main() {
		vec2 noise = vec2(
			.5+.5*snoise(vec3(vec2(aPosition*10.+200.), uTime*.5)),
			.5+.5*snoise(vec3(vec2(aPosition*10.+100.), uTime*.5))
		);

		if (aAge >= aLife) {
  if (uSpawnAtMouse) {
        // 出生在鼠标位置，并加一点随机偏移避免完全重叠
        vec2 randOffset = hash22(vec2(gl_VertexID)) * 0.02 - 0.01;
        vPosition = uMouse + randOffset;
        vAge = 0.;
        vLife = aLife;
        vVel = vec2(0.0);  // 初始速度为零或微小随机值
		vForce = vec2(0.0);
  vType = 1.0;
    } else {
        // 原有的噪声出生逻辑
        ivec2 coord = ivec2(gl_VertexID%512, gl_VertexID/512);
        vec2 rand = hash22(vec2(coord));
        float posX = snoise(vec3(rand+vec2(uRandom.x), -uTime*.1+noise.x*.1));
        float posY = snoise(vec3(rand-vec2(uRandom.y),  uTime*.1+noise.y*.1));
        vPosition = .75*vec2(posX, posY);
        vAge = 0.;
        vLife = aLife;
        vVel = vPosition;
		vForce = vec2(0.0);
		vType = 0.0;
    }
			// ivec2 coord = ivec2(gl_VertexID%512, gl_VertexID/512);
			// vec2 rand = hash22(vec2(coord));
			// float posX = snoise(vec3(rand+vec2(uRandom.x), -uTime*.1+noise.x*.1));
			// float posY = snoise(vec3(rand-vec2(uRandom.y),  uTime*.1+noise.y*.1));
			// vPosition = .75*vec2(posX, posY);
			// vAge = 0.;
			// vLife = aLife;
			// vVel = vPosition;
   // vForce = vec2(0.0);
		} else {
			vec2 force = 3.*(2.*noise.rg-1.);

   // 添加鼠标引力（仅当鼠标在画布内）
    if (uMouseActive > 0.5) {
        vec2 toMouse = uMouse - aPosition;
        float dist = length(toMouse);
        // 引力强度：距离越近越弱（避免过冲），可调整系数
        float strength = 0.03 * clamp(1.0 - dist * 0.5, 0.0, 1.0); //调整引力强度系数（0.03）和距离衰减因子（0.5）改变吸引力的明显程度
        force += strength * normalize(toMouse);
    }
			vPosition = aPosition+aVel*uTimeDelta;
			vAge = aAge+uTimeDelta;
			vLife = aLife;
			vVel = .95*aVel+force*uTimeDelta*3.;
   vForce = force;
   vType = aType;
		}
	}

`

const UPDATE_FRAG = `
	precision mediump float;
	in float vAge;
	void main() { discard; }
`

const RENDER_VERT = `
	precision mediump float;
	uniform vec2 uMouse;
	uniform bool uSpawnAtMouse;

	in vec4 aPosition;
	in float aAge;
	in float aLife;
	in vec2 aForce;
	 in vec2 aVel;
	in float aType;

	out vec4 vPosition;
	out float vAge;
	out float vLife;
	out vec2 vDebugMouse;
	out float vIsSpawning; // 修改：用 float 传递 uniform 状态
	out vec2 vDebugForce;
	out float vType;

	void main() {
		vPosition = aPosition;
		vAge = aAge;
		vLife = aLife;
		gl_PointSize = 1.*(1.-aAge/aLife);
		gl_Position = aPosition;
  vDebugMouse = uMouse; // 3. 将鼠标值塞进信道
  vIsSpawning = uSpawnAtMouse ? 1.0 : 0.0;
  vDebugForce = aForce.xy;
  vType = aType; // *** 赋值 ***
	}
`

const RENDER_FRAG = `
	precision mediump float;

	in float vAge;
	in float vLife;
	in vec2 vDebugMouse;
	in float vIsSpawning; // 接收 float
	in vec2 vDebugForce;
	in float vType;

	out vec4 fragColor;

	void main() {

if (vType > 0.5) {
			fragColor = vec4(1.0, 1.0, 0.0, 1.0);
		} else {
			fragColor = vec4(0.3, 0.0, 1.0, 1.0 - vAge/vLife);
		}
		// fragColor = vec4(vAge/vLife*1.0, .0, 1.0, 1.0);//rgb
  // fragColor = vec4(vType, 0.0, 1.0, 3.-2.*vAge/vLife);//rgb


  vec2 colorMap = vDebugMouse * 2.0 + 2.0;

		// 3. 输出颜色：红色代表鼠标的 X 坐标，绿色代表 Y 坐标
  vec2 dirMap = normalize(vDebugForce) * 0.5 + 0.5;
        // 如果 normalize 时 force 为 0，会产生 NaN，需要处理一下
        if (length(vDebugForce) < 0.001) { dirMap = vec2(0.0); }
		// fragColor = vec4(dirMap.x, dirMap.y, 0.0, 1.0 - vAge/vLife);
	}
`



// === Tab: tools.js ===

const random = (min = 0, max = 1) => {
	return Math.random() * (max - min) + min
}

const floor = (value) => {
	return Math.floor(value)
}

const min = (value1, value2) => {
	return Math.min(value1, value2)
}

